 const P={dashboard:'الرئيسية','my-day':'يومي',tasks:'المهام',goals:'الأهداف',planner:'المخطط',calendar:'التقويم',study:'موادي',tutor:'المساعد الذكي',assessments:'الاختبارات',knowledge:'خريطة المعرفة',progress:'تقدمي',insights:'رؤى المساعد',profile:'ما يتعلمه عني',settings:'الإعدادات','lesson-notes':'مراجعة المحاضرة'};
