 function today(d=new Date()){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
 function dval(x){return x?String(x).slice(0,10):''} function date(v,o={weekday:'long',month:'long',day:'numeric'}){if(!v)return'';let[y,m,d]=String(v).slice(0,10).split('-').map(Number);return new Intl.DateTimeFormat('ar-EG',o).format(new Date(y,m-1,d))}
