 function events(){let s=S.d?.schedule||{},base=[...(s.university_schedule||[]).map(e=>({...e,category:e.category||'class',fixed:true})),...(s.calendar_events||[])],out=[...base],now=new Date(),monthStart=new Date(S.cal.getFullYear(),S.cal.getMonth(),1),viewEnd=new Date(S.cal.getFullYear(),S.cal.getMonth()+1,7),start=new Date(Math.min(now.getTime(),monthStart.getTime()));start.setDate(start.getDate()-7);let end=new Date(Math.max(viewEnd.getTime(),now.getTime()+7*86400000));for(let e of base){if(e.recurring!=='weekly'||!e.date)continue;let d=new Date(`${dval(e.date)}T12:00:00`);if(Number.isNaN(d.getTime()))continue;if(d<start){let days=(start.getDay()-d.getDay()+7)%7;d=new Date(start);d.setDate(start.getDate()+days)}while(d<=end){if(today(d)>dval(e.date))out.push({...e,date:today(d),occurrence:true});d.setDate(d.getDate()+7)}}return out}
