 async function refresh(){try{S.d=await ProductAPI.load();render()}catch(e){toast(e.message,'error');if(!S.d)$('#dashboard-next-action').innerHTML=empty('تعذر الاتصال','شغّل الخدمة ثم أعد المحاولة.')}}
 let reconcilingPlan=false;async function reconcilePlan(){if(reconcilingPlan)return;reconcilingPlan=true;try{let r=await ProductAPI.reconcileSchedule(S.focus?.task_id);if(r.changed){await refresh();toast(`أعدت ترتيب ${r.rescheduled_tasks.length} مهمة لم تبدأ في موعدها.`, 'success')}}catch(e){console.warn('Schedule check unavailable:',e.message)}finally{reconcilingPlan=false}}
 function go(id){if(id==='more'){document.body.classList.add('menu-open');return}if(!P[id])return;S.page=id;document.body.classList.remove('menu-open');$$('.page').forEach(x=>x.classList.toggle('active',x.id===`page-${id}`));$$('.nav-item[data-page],.mobile-nav [data-page]').forEach(x=>x.classList.toggle('active',x.dataset.page===id));$('#header-section').textContent=['study','tutor','assessments','knowledge','lesson-notes'].includes(id)?'التعلّم':['progress','insights','profile'].includes(id)?'رؤى وتقدم':'مساحتك';$('#header-title').textContent=P[id];history.replaceState(null,'',`#${id}`);if(id==='calendar')renderCalendar();if(id==='my-day')renderDay();if(id==='planner')renderPlanner();if(id==='profile')renderProfile();if(id==='progress')renderProgress();if(id==='insights')renderInsights();if(id==='knowledge')renderKnowledge()}
