 async function renderAgentReadiness(){let box=$('#agent-readiness');if(!box)return;try{let s=await ProductAPI.agentStatus(),missing=s.missing_configuration||[],needs=s.missing_inputs||[];box.hidden=missing.length===0&&needs.length===0;box.innerHTML=`<span>جاهزية الوكلاء: ${s.ready_count} من ${s.count}</span>${missing.length?`<strong><i class="lucide-cable"></i> إعداد بعض الوكلاء مطلوب</strong><small>${missing.map(esc).join(' · ')}</small>`:''}${needs.length?`<strong><i class="lucide-list-plus"></i> معلومات تساعد الوكلاء على العمل</strong><small>${needs.map(esc).join(' · ')}</small>`:''}`}catch{box.hidden=false;box.textContent='تعذر التحقق من اتصال وكلاء الذكاء الاصطناعي.'}}
 function nextTask(){let planned=nextPlannedTask();if(planned)return planned;let t=today();return [...openTasks()].sort((a,b)=>{let x=dval(a.deadline)||dval(a.scheduled_date)||'9999-12-31',y=dval(b.deadline)||dval(b.scheduled_date)||'9999-12-31';return(x<t?-1:0)-(y<t?-1:0)||x.localeCompare(y)||Number(b.priority_weight||3)-Number(a.priority_weight||3)})[0]||null}
 function nextPlannedTask(){let now=new Date(),hhmm=`${String(now.getHours()).padStart(2,'0')}:${String(now.getMinutes()).padStart(2,'0')}`,block=(S.d?.schedule?.scheduled_blocks||[]).filter(b=>dval(b.date)===today()&&b.end>hhmm&&openTasks().some(t=>t.task_id===b.task_id)).sort((a,b)=>a.start.localeCompare(b.start))[0],task=block&&openTasks().find(t=>t.task_id===block.task_id);return task?{...task,focus_duration_mins:block.duration_mins}:null}
 function eventRow(x){let c=x.category||'study';return `<div class="event-row"><span class="event-time">${esc(x.start||'—')}</span><span class="event-indicator ${['personal','work'].includes(c)?'personal':['exam','deadline'].includes(c)?'deadline':'study'}"></span><div class="event-title">${esc(x.title)}<div class="event-sub">${esc(C[c]||c)} · ${esc(date(x.date,{month:'short',day:'numeric'}))}</div></div>${x.task?`<button class="icon-button" data-focus-task="${esc(x.id)}"><i class="lucide-play"></i></button>`:`<button class="icon-button" data-edit-event="${esc(x.id)}"><i class="lucide-pencil"></i></button>`}</div>`}
 function renderDashboard(){let n=nextTask(),goal=(S.d?.goals?.goals||[]).find(g=>g.goal_id===n?.goal_id);$('#dashboard-next-action').innerHTML=n?`<h2 class="next-action-title">${esc(n.title)}</h2><div class="next-action-meta"><span class="tag">${esc(C[n.category||n.topic_ref]||n.topic_ref||'مهمة')}</span> · ${n.focus_duration_mins||n.remaining_mins||n.estimated_mins||30} دقيقة${n.deadline?' · موعدها '+esc(date(dval(n.deadline),{month:'short',day:'numeric'})):''}</div><p class="next-action-reason">${goal?`خطوة نحو هدفك: ${esc(goal.title)}. `:''}${esc(n.rationale||'اقتراح حسب الموعد والأولوية؛ يمكنك تغييره.')}</p><div class="next-action-actions">${primaryTaskAction(n,n.focus_duration_mins||0)}<button class="button button-secondary" data-page-link="tasks">كل المهام</button></div>`:(!events().length&&!tasks().length?`<h2 class="next-action-title">ابدأ بجدولك الأسبوعي</h2><p class="next-action-meta">ارفع صورة جدولك، راجع المواعيد، ثم أضف ما تريد إنجازه.</p><div class="next-action-actions"><button class="button button-primary" data-page-link="planner"><i class="lucide-image-up"></i> ارفع صورة جدولك</button><button class="button button-secondary" data-action="add-goal"><i class="lucide-target"></i> اكتب هدفًا</button></div>`:`<h2 class="next-action-title">مساحتك جاهزة</h2><p class="next-action-meta">أضف مواعيدك ومهامك. لن أملأ جدولك بدلًا منك.</p><div class="next-action-actions"><button class="button button-primary" data-action="add-event"><i class="lucide-calendar-plus"></i> أضف موعدًا</button><button class="button button-secondary" data-action="add-task"><i class="lucide-plus"></i> مهمة جديدة</button></div>`);
 let ds=today(),planned=tasks().filter(t=>dval(t.scheduled_date)===ds),done=planned.filter(t=>t.status==='completed').length,pct=planned.length?Math.round(done/planned.length*100):0;$('#dashboard-progress').innerHTML=`<div class="progress-meta"><span>${done} من ${planned.length} مهام</span><strong>${pct}%</strong></div><div class="progress-track"><div class="progress-fill" style="width:${pct}%"></div></div><p class="event-sub">${planned.length?'تقدمك من مهامك المسجلة.':'أضف أول مهمة ليظهر تقدم يومك.'}</p>`;
 let up=[...events().filter(x=>dval(x.date)>=ds),...openTasks().filter(t=>t.deadline).map(t=>({id:t.task_id,title:t.title,date:dval(t.deadline),start:'23:59',category:'deadline',task:true}))].sort((a,b)=>(a.date+a.start).localeCompare(b.date+b.start)).slice(0,5);$('#dashboard-upcoming').innerHTML=up.length?`<div class="event-list">${up.map(eventRow).join('')}</div>`:empty('مافيش مواعيد قريبة','أدخل محاضراتك والتزاماتك؛ وسأرتب المهام حولها.','add-event','أضف موعدًا');
 let gs=(S.d.goals.goals||[]).filter(g=>g.status!=='completed').slice(0,3);$('#dashboard-goals').innerHTML=gs.length?gs.map(g=>`<div class="goal-progress"><div class="progress-meta"><span>${esc(g.title)}</span><b>${goalPct(g)}%</b></div><div class="progress-track"><div class="progress-fill" style="width:${goalPct(g)}%"></div></div></div>`).join(''):empty('ابدأ بهدف واحد','اكتب ما تريد تحقيقه.','add-goal','أضف هدفًا');let p=(S.d.predictions||[]).find(x=>x.status==='active');$('#dashboard-insight').innerHTML=p?`<p class="insight-copy">${esc(p.preemptive_action||p.rationale)}</p><span class="insight-evidence">${esc(p.rationale||'مبني على بياناتك المسجلة.')}</span>`:`<p class="insight-copy">${tasks().length?'سأبني اقتراحاتي على مواعيدك ومهامك.':'أحتاج بيانات فعلية قبل استنتاج نمطك.'}</p><span class="insight-evidence">لا توجد استنتاجات تخمينية.</span>`}
