 function renderTasks(){let cat=$('#task-category-filter').value,rows=tasks().filter(t=>S.filter==='all'||(S.filter==='open'&&!['completed','missed'].includes(t.status))||(S.filter==='completed'&&t.status==='completed'));if(cat!=='all')rows=rows.filter(t=>(t.category||'study')===cat);$('#tasks-list').innerHTML=rows.length?rows.map(t=>{let course=(S.d.courses||[]).find(c=>c.course_id===t.course_id),goal=(S.d.goals.goals||[]).find(g=>g.goal_id===t.goal_id);return `<article class="task-row" draggable="${t.task_kind==='assessment'?'false':'true'}" data-drag-task="${esc(t.task_id)}"><input class="task-check" type="checkbox" ${t.status==='completed'?'checked':''} ${t.task_kind==='assessment'?'disabled':''} data-complete-task="${esc(t.task_id)}" aria-label="تأكيد إنجاز ${esc(t.title)}"><div class="task-main"><div class="task-title ${t.status==='completed'?'completed':''}">${esc(t.title)}</div><div class="task-meta"><span class="tag">${t.task_kind==='assessment'?'اختبار قصير':esc(C[t.category||'study']||t.category||'دراسة')}</span>${course?`<span>${esc(course.course_name)}</span>`:''}${t.topic_ref?`<span>${esc(t.topic_ref)}</span>`:''}${goal?`<span>هدف: ${esc(goal.title)}</span>`:''}<span>${t.remaining_mins||t.estimated_mins||30} د</span>${t.scheduled_date?`<span>في ${esc(date(dval(t.scheduled_date),{month:'short',day:'numeric'}))}</span>`:''}${t.deadline?`<span>موعد نهائي ${esc(date(dval(t.deadline),{month:'short',day:'numeric'}))}</span>`:''}<span class="priority ${Number(t.priority_weight)>=4?'high':Number(t.priority_weight)<=2?'low':'medium'}">${Number(t.priority_weight)>=4?'عالية':Number(t.priority_weight)<=2?'منخفضة':'متوسطة'}</span></div></div><div class="task-actions">${studyTaskAction(t)}${taskStartButton(t)}<button class="icon-button" data-edit-task="${esc(t.task_id)}" aria-label="تعديل"><i class="lucide-pencil"></i></button><button class="icon-button" data-delete-task="${esc(t.task_id)}" aria-label="حذف"><i class="lucide-trash-2"></i></button></div></article>`}).join(''):empty('لا توجد مهام هنا','أضف مهام الدراسة والشغل والحياة.','add-task','أضف مهمة')}
 function goalPct(g){let m=g.milestones||[];return m.length?Math.round(m.filter(x=>x.status==='completed').length/m.length*100):Number(g.progress||0)}
 function renderGoals(){let gs=S.d?.goals?.goals||[],hs=S.d?.goals?.habits||[],badges=S.d?.goals?.achievements||[];$('#goals-list').innerHTML=gs.length?gs.map(g=>{let a=g.action_plan||{},t=a.task;let action=a.status==='today'&&t?`<div class="goal-next-action"><div><span class="eyebrow">خطوتك اليوم</span><b>${esc(t.title)}</b><small>${a.start?`الساعة ${esc(a.start)} · `:''}${a.duration_mins||t.remaining_mins||t.estimated_mins||30} دقيقة${a.milestone_title?` · ${esc(a.milestone_title)}`:''}</small><small>${esc(a.reason||'خطوة مرتبطة بهدفك.')}</small></div><button class="button button-primary" data-focus-task="${esc(t.task_id)}" data-focus-minutes="${Number(a.duration_mins||t.remaining_mins||t.estimated_mins||30)}" aria-label="ابدأ ${esc(t.title)}"><i class="lucide-play"></i> ابدأ</button></div>`:a.status==='upcoming'&&t?`<div class="goal-next-action muted"><div><span class="eyebrow">الخطوة التالية</span><b>${esc(t.title)}</b><small>${a.date?`مجدولة ${esc(date(dval(a.date),{month:'short',day:'numeric'}))}`:'غير مجدولة بعد'} · ${a.duration_mins||t.estimated_mins||30} دقيقة</small><small>${esc(a.reason||'')}</small></div><button class="button button-secondary" data-page-link="tasks">عرض</button></div>`:a.status==='needs_task'?`<div class="goal-next-action muted"><div><span class="eyebrow">الخطوة التالية</span><b>لا توجد مهمة مرتبطة بهذا الهدف بعد</b><small>أضف خطوة عملية وسأرتبها ضمن يومك.</small></div><button class="button button-secondary" data-action="add-task" data-goal-id="${esc(g.goal_id)}" data-milestone-id="${esc(a.milestone_id||'')}">أضف خطوة</button></div>`:'';return `<article class="panel goal-card"><div class="panel-heading"><span class="tag">${esc(C[g.category]||g.category||'هدف')}</span><button class="icon-button" data-delete-goal="${esc(g.goal_id)}"><i class="lucide-trash-2"></i></button></div><h3>${esc(g.title)}</h3><p class="goal-description">${esc(g.description||g.why||'هدفك، تقدّم فيه بالطريقة التي تناسب حياتك.')}</p>${examBanner(g)}<div class="goal-progress"><div class="progress-meta"><span>التقدم</span><b>${goalPct(g)}%</b></div><div class="progress-track"><div class="progress-fill" style="width:${goalPct(g)}%"></div></div></div>${action}<div class="goal-milestones">${(g.milestones||[]).map(m=>`<label class="milestone-row"><input type="checkbox" data-milestone="${esc(g.goal_id)}|${esc(m.id)}" ${m.status==='completed'?'checked':''}><span>${esc(m.title)}</span></label>`).join('')}</div></article>`}).join(''):empty('ابدأ بهدف واحد','ما الذي يهمك في الدراسة أو الشغل أو حياتك؟','add-goal','أضف هدفك الأول');$('#habits-list').innerHTML=hs.length?`<div class="habit-list">${hs.map(h=>`<div class="event-row"><span class="event-indicator study"></span><div class="event-title">${esc(h.name)}<div class="event-sub">${Number(h.streak||0)} يوم متتابع · أفضل سلسلة ${Number(h.best_streak||0)}</div></div><button class="button button-secondary" data-checkin-habit="${esc(h.name)}" ${h.last_completed===today()?'disabled':''}>${h.last_completed===today()?'تم اليوم':'سجل اليوم'}</button></div>`).join('')}</div>`:empty('ابدأ بعادة صغيرة','أضف عادة تهمك، وسجلها عندما تنجزها.','add-habit','أضف عادة');if(badges.length)$('#habits-list').insertAdjacentHTML('beforeend',`<div class="badge-list">${badges.map(b=>`<span class="tag">${esc(b.title)}</span>`).join('')}</div>`)}
