 function renderProgress(){let d=S.d,done=tasks().filter(t=>t.status==='completed').length,total=tasks().length,gs=d.goals.goals||[],hs=d.assessments||[],days=S.range,start=new Date();start.setDate(start.getDate()-days+1);let daily=Array.from({length:Math.min(days,30)},(_,i)=>{let x=new Date(start);x.setDate(start.getDate()+i);let iso=today(x);return{iso,n:tasks().filter(t=>t.status==='completed'&&dval(t.scheduled_date)===iso).length}}),max=Math.max(1,...daily.map(x=>x.n));$('#progress-content').innerHTML=`<div class="stat-strip"><div class="stat-card"><small>مهام مكتملة</small><strong>${done}</strong></div><div class="stat-card"><small>نسبة الإكمال</small><strong>${total?Math.round(done/total*100):0}%</strong></div><div class="stat-card"><small>أهداف نشطة</small><strong>${gs.filter(g=>g.status==='active').length}</strong></div><div class="stat-card"><small>اختبارات</small><strong>${hs.length}</strong></div></div><div class="panel"><div class="panel-heading"><div><span class="eyebrow">${days} يومًا</span><h2>المهام المكتملة</h2></div></div>${total?`<div class="data-bars">${daily.map(x=>`<div class="data-bar-column"><div class="data-bar" style="height:${Math.max(2,x.n/max*100)}%"></div><span class="data-bar-label">${new Date(x.iso+'T12:00:00').getDate()}</span></div>`).join('')}</div>`:empty('ابدأ بتسجيل مهامك','سيظهر تقدمك الفعلي هنا.')}</div><div class="panel" style="margin-top:13px"><div class="panel-heading"><div><span class="eyebrow">قياس فعلي</span><h2>أداء الاختبارات</h2></div></div>${hs.length?hs.slice(0,5).map(a=>`<div class="event-row"><span class="event-indicator study"></span><div class="event-title">${esc(a.topic||a.course_name||'مادة')}</div><b>${Number(a.evaluation?.score_pct??a.score_pct??0)}%</b></div>`).join(''):empty('لا توجد اختبارات','أكمل اختبارًا لقياس تقدمك.')}</div>`}
 function renderInsights(){let model=S.d?.model||{},ps=(S.d?.predictions||[]).filter(p=>p.status==='active'),open=openTasks(),overdue=open.filter(t=>t.deadline&&dval(t.deadline)<today()),dueSoon=open.filter(t=>t.deadline&&dval(t.deadline)>=today()&&dval(t.deadline)<=today(new Date(Date.now()+3*86400000))),plannedToday=open.filter(t=>dval(t.scheduled_date)===today()),todayMins=plannedToday.reduce((sum,t)=>sum+Number(t.remaining_mins||t.adjusted_mins||t.estimated_mins||0),0),weak=[...new Set(model.weak_topics||[])],context=model.topic_context||{},rows=ps.map(p=>`<article class="panel insight-card"><span class="eyebrow">توقع مبني على سلوكك</span><h3>${esc(p.rationale||'مخاطر تحتاج مراجعة')}</h3><p>${esc(p.preemptive_action||'راجع توزيع وقتك.')}</p><span class="tag">مستوى الخطر ${Math.round((p.risk_score||0)*100)}%</span><button class="button button-secondary" data-page-link="planner">راجع الخطة</button></article>`);if(overdue.length)rows.push(`<article class="panel insight-card"><span class="eyebrow">موعد فات</span><h3>${overdue.length} مهمة مفتوحة تجاوزت موعدها</h3><p>${overdue.slice(0,3).map(t=>esc(t.title)).join(' · ')}. الخطة ستعيد ترتيبها؛ راجع الموعد إن كان تغيّر.</p><button class="button button-secondary" data-page-link="tasks">راجع المهام</button></article>`);if(dueSoon.length){let mins=dueSoon.reduce((sum,t)=>sum+Number(t.remaining_mins||t.adjusted_mins||t.estimated_mins||0),0);rows.push(`<article class="panel insight-card"><span class="eyebrow">استحقاقات قريبة</span><h3>${dueSoon.length} مهام · ${mins} دقيقة حتى خلال ٣ أيام</h3><p>${dueSoon.slice(0,3).map(t=>`${esc(t.title)} · ${esc(date(dval(t.deadline),{month:'short',day:'numeric'}))}`).join('<br>')}</p><button class="button button-secondary" data-page-link="planner">وزّع وقتك</button></article>`)}if(todayMins>Number(model.max_daily_study_mins||240))rows.push(`<article class="panel insight-card"><span class="eyebrow">حمل اليوم</span><h3>${todayMins} دقيقة مخططة</h3><p>تقدير وقت مهامك يتجاوز حدك اليومي المسجل (${Number(model.max_daily_study_mins||240)} دقيقة).</p><button class="button button-secondary" id="optimize-from-insight">أعد توزيع الأسبوع</button></article>`);if(weak.length)rows.push(...weak.slice(0,4).map(topic=>{let c=context[topic]||{};return `<article class="panel insight-card"><span class="eyebrow">فجوة من إجابات اختبارك</span><h3>${esc(topic)}</h3><p>${esc(c.course_name||'موضوع من اختبار سابق')}${c.lecture_id?' · المحاضرة المرتبطة':''}. سأبدأ من المادة التي أخطأت فيها.</p><div class="button-row"><button class="button button-secondary" data-study-topic="${esc(topic)}" data-course-id="${esc(c.course_id||'')}" data-lecture-id="${esc(c.lecture_id||'')}">افهمها مع المساعد</button>${c.course_id&&c.lecture_id?`<button class="button button-primary" data-test-topic="${esc(topic)}" data-course-id="${esc(c.course_id)}" data-lecture-id="${esc(c.lecture_id)}">اختبرها</button>`:''}</div></article>`}));if((model.focus_sessions_count||0)>=3&&model.peak_productivity_window)rows.push(`<article class="panel insight-card"><span class="eyebrow">نمط متعلم من جلساتك</span><h3>وقت تركيزك الأقوى ${esc(model.peak_productivity_window)}</h3><p>أستخدم النمط ده عند ترتيب الجلسات عالية التركيز.</p></article>`);$('#insights-content').innerHTML=rows.join('')||empty('لسه مفيش نمط أو خطر مؤكد','هنا هتظهر مخاطر المواعيد ونقاط ضعف الكويز لما يكون عندنا دليل من جدولك ونتايجك.')}
 function openNotifications(){let ps=(S.d?.predictions||[]).filter(p=>p.status==='active').map(p=>({title:p.rationale||'مراجعة مطلوبة',detail:p.preemptive_action||'راجع خطتك',icon:'lucide-lightbulb'})),now=today(),upcoming=[...events().filter(x=>dval(x.date)>=now&&dval(x.date)<=today(new Date(Date.now()+7*86400000))).map(x=>({title:x.title,detail:`${date(x.date)} · ${x.start||''}`,icon:'lucide-calendar-days'})),...openTasks().filter(t=>t.deadline&&dval(t.deadline)>=now&&dval(t.deadline)<=today(new Date(Date.now()+7*86400000))).map(t=>({title:t.title,detail:`موعد التسليم · ${date(t.deadline)}`,icon:'lucide-clock'}))];let rows=[...ps,...upcoming];$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true"><div class="modal-head"><div><span class="eyebrow">من واقع خطتك</span><h2>التنبيهات</h2></div><button class="icon-button" data-close aria-label="إغلاق"><i class="lucide-x"></i></button></div>${rows.length?rows.map(x=>`<div class="event-row"><i class="${x.icon} notification-icon"></i><div class="event-title">${esc(x.title)}<div class="event-sub">${esc(x.detail)}</div></div></div>`).join(''):empty('لا توجد تنبيهات الآن','ستظهر هنا المواعيد القريبة والمخاطر التي رصدتها بياناتك.')}</section></div>`}
