 function closeModal(force=false){if(!force&&$('#onboarding-form'))return;$('#modal-root').innerHTML='';} function formElement(value){if(value instanceof HTMLFormElement)return value;if(value?.target instanceof HTMLFormElement)return value.target;if(value?.currentTarget instanceof HTMLFormElement)return value.currentTarget;throw new TypeError('تعذر تحديد النموذج المرسل. حدّث الصفحة وحاول مرة أخرى.')} function formBody(value){const o={};new FormData(formElement(value)).forEach((v,k)=>o[k]=String(v).trim());return o;}
