 function focusStart(id,duration){S.focus=tasks().find(t=>t.task_id===id)||null;let now=new Date(),nextBlock=(S.d?.schedule?.scheduled_blocks||[]).filter(b=>b.task_id===id&&(dval(b.date)>today()||(dval(b.date)===today()&&b.end>`${String(now.getHours()).padStart(2,'0')}:${String(now.getMinutes()).padStart(2,'0')}`))).sort((a,b)=>(a.date+a.start).localeCompare(b.date+b.start))[0];S.focusPlannedMins=Math.max(1,Number(duration||nextBlock?.duration_mins||S.focus?.remaining_mins||S.focus?.estimated_mins||25));S.sec=S.focusPlannedMins*60;S.focusElapsed=0;$('#focus-task-name').textContent=S.focus?.title||'جلسة تركيز مستقلة';$('#focus-done').onclick=()=>focusEnd('completed');$('#focus-continue').onclick=()=>focusEnd('session');$('#focus-more').onclick=extendFocus;$('#focus-reschedule').onclick=()=>focusEnd('cut_short');$('#focus-expired-actions').hidden=true;$('#focus-expired-message').hidden=true;$('#focus-toggle').hidden=false;$('#focus-finish').hidden=false;$('#focus-overlay').classList.add('active');clock()}
 function clock(){$('#focus-clock').textContent=`${String(Math.floor(S.sec/60)).padStart(2,'0')}:${String(S.sec%60).padStart(2,'0')}`}
 function toggleFocus(){if(S.timer){clearInterval(S.timer);S.timer=null;$('#focus-toggle').innerHTML='<i class="lucide-play"></i> استكمل';return}$('#focus-toggle').innerHTML='<i class="lucide-pause"></i> توقف مؤقت';S.timer=setInterval(()=>{S.sec--;S.focusElapsed++;clock();if(S.sec<=0){S.sec=0;clock();clearInterval(S.timer);S.timer=null;$('#focus-toggle').hidden=true;$('#focus-finish').hidden=true;$('#focus-expired-message').hidden=false;$('#focus-expired-actions').hidden=false}},1000)}
 async function focusEnd(outcome='abandon'){clearInterval(S.timer);S.timer=null;$('#focus-overlay').classList.remove('active');if(S.focus&&outcome!=='abandon'&&S.focusElapsed>0){try{let actual=Math.max(1,Math.ceil(S.focusElapsed/60));if(outcome==='session')await ProductAPI.logFocusSession(S.focus.task_id,actual,S.focusPlannedMins);else await ProductAPI.setTaskStatus(S.focus.task_id,outcome,actual,S.focusPlannedMins);await refresh();toast(outcome==='completed'?'سجلت إنجاز المهمة ووقتك الفعلي':outcome==='session'?'سجلت الجلسة؛ المهمة ما زالت مفتوحة وأعدت ترتيبها':'سجلت وقت الجلسة وأعدت ترتيب المهمة',outcome==='completed'?'success':'')}catch(x){toast(x.message,'error')}}S.focus=null;S.focusElapsed=0;reconcilePlan()}
